name: Update Roadmap on Merge

on:
  pull_request_target:
    types: [closed]

jobs:
  update-roadmap:
    if: github.event.pull_request.merged == true && github.event.pull_request.base.ref == 'main'
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0
          token: ${{ secrets.GITHUB_TOKEN }}

      - name: Set up Node
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Update roadmap
        run: |
          PR_NUMBER=${{ github.event.pull_request.number }}
          ROADMAP_FILE="docs/roadmap.md"

          if [ ! -f "$ROADMAP_FILE" ]; then
            echo "Roadmap file $ROADMAP_FILE not found. Skipping."
            exit 0
          fi

          node <<'NODE'
          const fs = require('fs');
          const filePath = process.env.ROADMAP_FILE;
          const prNumber = process.env.PR_NUMBER;

          let content = fs.readFileSync(filePath, 'utf8');
          const sectionHeader = '10 most recent merged PRs';
          const regex = new RegExp(`(${sectionHeader}\\n- #\\d+(\\n- #\\d+){0,9})`, 'g');
          const match = content.match(regex);

          if (!match) {
            console.log('Section not found. Skipping.');
            process.exit(0);
          }

          const list = match[0].split('\n').slice(1).map(line => line.trim());
          const newList = [`- #${prNumber}`, ...list];
          const finalList = newList.slice(0, 10);
          const newSection = sectionHeader + '\n' + finalList.join('\n');

          content = content.replace(regex, newSection);
          fs.writeFileSync(filePath, content, 'utf8');
          console.log('Roadmap updated.');
          NODE
        env:
          ROADMAP_FILE: ${{ env.ROADMAP_FILE }}
          PR_NUMBER: ${{ github.event.pull_request.number }}

      - name: Commit and push changes
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "github-actions[bot]@users.noreply.github.com"
          git add $ROADMAP_FILE
          git commit -m "Update roadmap: add merged PR #${{ github.event.pull_request.number }}"
          git push
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
